    bag_examples_v2_toast: "🎁 Nya exempel i din väska: presentidéer, en packlista för hotellet och en för flyget ✨",
    faq_a_bag_examples_list: "En ny väska kommer med exempel som du kan ändra eller ta bort precis som allt annat: Hem (inköp, recept, veckans måltider), Familj (små ögonblick, en lista för födelsedagskalaset, aktiviteter och kurser), Idéer (idéer för helgen, presentidéer efter hur nära personen står dig och vad du ska göra med sparade pengar) och Resor (platser du vill åka till, packlista för resan, packlista för hotellet och en lista för att flyga utomlands). En väska som redan fanns får de nyaste en gång, i sina egna fack.",
    faq_q_bag_examples_list: "Vilka exempel finns i Min väska?",
    faq_a_nm_me1_guide: "Sky – din karaktär i New Me, i sin första form (Sky 1). Första gången, direkt efter att du gått med, öppnas en portal av ljus med gnistor runt omkring och Sky flyger ut ur den, förklarar med några tryck vad som väntar och stannar sedan bredvid varje fråga: medan måltiderna väljs skriver han med dig i sin bok, och ett tryck på hans tips visar ett till. I slutet firar Sky med dig och tar med dig på en kort rundtur – och när rundturen är slut har han ett litet ögonblick till med dig. Om du går mitt i – frågorna eller rundturen – blir Sky glad att se dig nästa gång och frågar om ni ska fortsätta från samma ställe.",
