    nm_m1_skip: "Hoppa över",
    nm_m1_tip_ai: "En maträtt som inte finns på listan? Senare kan du skriva den med egna ord under \"Byt\" – och AI räknar ut den. Och nu väljer vi tillsammans vad du ska äta varje dag.",
