    room_genie_rest: "Skogsanden vilar nu – kom tillbaka i morgon ✨",
    faq_a_shop_holidays: "Tryck på presenten i Inköpslistan: högtiderna i ditt land (det som är valt i Inställningar) visas i tur och ordning, med datum – som räknas ut av sig själva varje år. Tryck på en högtid för en färdig lista med det man brukar köpa till den; allt är markerat (utom det som redan finns på din lista), avmarkera det du inte behöver och tryck på ”Lägg till i listan”. Två veckor före en högtid dyker ett litet kort upp högst upp i listan; ✕ döljer det till nästa högtid.",
    faq_q_shop_holidays: "Hur fungerar ”Vad ska köpas till högtiden”?",
    shop_hol_add: "Lägg till i listan ({n})",
    shop_hol_added: "Tillagt i listan: {n}",
    shop_hol_btn: "Vad ska köpas till högtiden",
    shop_hol_items_title: "{holiday} – vad ska köpas?",
    shop_hol_not_now: "Inte nu",
    faq_a_shop_delivery: "Tryck på lastbilen i Inköpslistan: välj vad som ingår i leveransen (allt är markerat), när den kommer – idag, imorgon eller en annan dag – och vilken tid (förmiddag, eftermiddag, kväll eller ”Annan…” för egna tider). De varorna flyttas till kortet ”På väg” högst upp i listan, med dagen och tiderna. När dagen kommer visas ”Har leveransen kommit?” i Min Dag (och kortet har ”Har den kommit?”). Har allt kommit flyttas de till ”Köp igen”. Saknas något trycker du på det som inte kom, så går det direkt tillbaka till listan.",
    faq_a_shop_departments: "Listan sorterar sig själv efter avdelningarna i matbutiken – frukt & grönt, bröd, mejeri & ägg, kött & fisk, skafferi, fryst, drycker, snacks, städ, hygien, barn och husdjur – så att du går gångarna i ordning. Avdelningen känns igen på varans namn. Hamnade en vara på fel ställe, tryck på den och välj avdelning, eller ”Övrigt…” för att skriva en egen.",
    faq_a_shop_share_qty: "Ja. Bredvid varje vara lägger + till en (×2, ×3…) och − tar bort en. Dela-knappen högst upp i Inköpslistan skickar hela listan, snyggt sorterad efter avdelning, via WhatsApp, e-post eller som en kopia.",
    faq_a_shop_two_buttons: "Båda betyder ”köpt”. ✕ är för något du köper en gång – det försvinner från listan (och väntar i arkivet 🗑️ ifall det blev fel). ↺ är för saker du köper om och om igen – de försvinner från listan och väntar i ”Köp igen”: den lilla ↺-knappen bredvid papperskorgen längst ner i listan öppnar det, och ett tryck där lägger tillbaka en vara på listan. Under ”Redigera” där inne kan du ta bort en vara därifrån. När du lägger till en vara dyker saker du har köpt förut upp som förslag, och om den redan finns på listan blir den bara ×2 i stället för en andra rad.",
