    nm_demo_title: "Så fungerar ett byte",
    faq_a_new_me_challenge_journal: "När en utmaning tar slut – stor, mini eller veckans utmaning – finns en knapp 📝 Hur gick det? i firandet. Den öppnar en sida i utmaningsdagboken: hur det kändes (fem ansikten), vad som hjälpte, vad som var svårt och vad jag tar med mig – inget av det är obligatoriskt, och det kan också vänta till senare. Dagboken är en diamant i den magiska ryggsäcken: varje avslutad utmaning med datum och det som skrevs, den nyaste först – tryck på en för att läsa, redigera eller dela den (bara det som står på sidan delas). En avslutad utmaning får också en medalj bland prestationerna, under ”Utmaningar jag har klarat”. Utmaningsdagboken är skild från den vanliga dagboken.",
    faq_q_new_me_challenge_journal: "Vad är utmaningsdagboken?",
