    nm_chj_write: "Skriv hur det gick",
    nm_swap_time: "Tid",
    faq_a_ai_reminder_in_text: "Ja – skriv den tillsammans med uppgiften, till exempel ”i morgon kl. 17:00 hämta paketet, med en påminnelse en timme innan”. Påminnelsen sparas på själva uppgiften: en timme innan, en halvtimme, dagen innan och så vidare, och ”påminn mig” utan tid betyder 10 minuter innan. En påminnelse som skrivs i texten har företräde framför påminnelsefältet i samma fönster.",
    faq_q_ai_reminder_in_text: "Kan jag be AI-assistenten om en påminnelse i samma förfrågan?",
    myday_meals_all_done: "Alla dagens måltider är avbockade 🍽️",
    nm_tour_week_text: "En liten utmaning för veckan. ✓ varje dag – en nyckel i slutet.",
    books_home_chip: "{title} · s. {page}",
    books_home_of: "av {total}",
    books_home_off_toast: "Boken togs bort från hemskärmen",
    books_home_on_toast: "Boken finns på hemskärmen 📖",
    books_home_pin: "På hemskärmen",
    books_home_q: "Vilken sida är jag på?",
    books_home_save: "Spara",
    faq_a_books_home_chip: "Ja. I Läshörna, på kortet för en bok du läser just nu, trycker du på 📌 På hemskärmen. En liten knapp med boken och sidan visas under hälsningen på hemskärmen – tryck på den, skriv det nya sidnumret och spara, så följs framstegen (även i Läshörna). Tryck på 📌 igen så tas den bort. Flera böcker kan finnas där samtidigt – en knapp för varje – och samma på alla enheter.",
    faq_a_new_me_week_challenge: "En liten utmaning för en vecka, som du väljer själv. I korridoren finns ett stort kort: ”Vad vill du jobba med den här veckan?” – tryck på det, välj ett område (med mig själv, med andra, lära och växa, lugn, små modiga steg, hem och rutiner) och en utmaning, och bestäm när den börjar. Samma utmaningar finns också på utmaningsskärmen, under 🌱 Personlig utveckling. Varje dag bockar du av ✓ på kortet (en fridag i veckan), och varje vecka som tar slut ger en ny nyckel till den hemliga världen. ”Läsa 2 sidor om dagen” bockas av automatiskt utifrån sidorna som loggas i Läshörna. När veckan är slut lägger 📌 Behåll som daglig uppgift till den i Min Rutin vid den tid du väljer, med en ✓ varje dag. En veckoutmaning pågår åt gången; de stora utmaningarna och miniutmaningarna fortsätter vid sidan om.",
    faq_a_room_genie: "På verandan vid havet får ett tryck på Aladdins lampa skogsanden att stiga fram – och ett samtal börjar: vad önskar du dig (vad skulle du vilja förändra i ditt liv), hur det kommer kännas när det går i uppfyllelse, vad som är svårt på vägen och hur situationen just nu kan vändas till något bra. Sedan ungefär hur lång tid det tar, ett första litet steg och två till, och ett ”om… så…” för när det blir svårt. Till sist visas hela önskan steg för steg, och den kan bli ett mål i Mina Mål (stegen blir milstolpar på stigen, med datum efter den tid som valts; där kan allt ändras) eller sparas i dagboken – och sedan säger skogsanden adjö. Ingenting sparas om man inte väljer något av dem. Från andra besöket frågar skogsanden först om du skulle vilja förändra något mer i ditt liv: ja – samma samtal; inte just nu – en påminnelse om att nå de mål som redan satts upp. Skogsanden kommer fram en gång om dagen: när en önskan har sparats (eller efter ”Inte just nu”) vilar den till i morgon. Frågorna följer ett välkänt sätt att göra en önskan till en plan: önskan, resultat, hinder och plan.",
    faq_q_books_home_chip: "Kan jag se min bok och sida på hemskärmen?",
    faq_q_new_me_week_challenge: "Vad är veckans utmaning?",
    faq_q_room_genie: "Vad gör lampans ande?",
