    faq_a_new_me_game: "I New Me stannar spelknapparna alltid på samma plats – i korridoren, i det hemliga rummet och överallt i skogen; bara målningen i mitten byts. Högst upp: dagen på resan, nycklar, dagar i rad och dagens energi (hur mycket som har ätits av planen), och under det nästa uppdrag – nästa måltid med klockslag (ett tryck öppnar den, med ✓ Jag har ätit). På sidan: hela dagen, utmaningar och min resa, och bredvid dem veckans utmaning – dess 7 dagar och en ✓ för i dag. Längst ner: den magiska ryggsäcken (hela New Me – världskartan, min resa, inköpslista, prestationer, utmaningsdagbok, kroppsmått, bilder, månadskalender, dagstabell, påminnelser, meny-PDF och inställningar; den öppnas som en egen skärm). Världskartan, det första i ryggsäcken, visar alla platser i skogen – tryck på en plats för att gå dit; på en låst plats syns hur många nycklar den behöver. Sky är din karaktär på skogsstigen: han börjar som Sky 1, efter några utmaningar (4 nycklar) växer han till Sky 2 och mot slutet (9 nycklar) till Sky 3 – med en förvandling som går att se. Tryck på Sky för att se alla steg – varje steg som redan nåtts kan väljas igen, så ett tidigare kan komma tillbaka. Sky svävar – dra honom med fingret eller musen, och ingången han rör vid öppnas (en låst visar hur många nycklar som saknas). Sky följer också med in i varje rum och på varje plats och svävar där du lämnar honom: dra honom vart du vill, och dra den lysande ringen under honom för att vända honom hela varvet runt; han tittar åt det håll han rör sig (på en dator: pilarna flyttar honom, Q och E vrider honom). I korridoren går den lilla 🏠 under det övre fältet tillbaka till hemskärmen; i varje rum och på varje plats går knappen i samma hörn tillbaka till korridoren.",
    faq_q_new_me_game: "Hur fungerar spelknapparna, världskartan och Sky?",
