    faq_a_new_me_menu_build: "Först frågar frågeformuläret vilka måltider du äter och när (2 måltider + ett mellanmål, 2 måltider + en lätt middag, eller båda), och om det blir något på kvällen – att äta eller dricka, vad och vilken tid. Med ”2 måltider + ett mellanmål” är måltiderna lunch (11:30) och middag (19:00), med mellanmålet kl. 16:00. Sedan visas alla alternativ för de måltiderna. Välj upp till 2 favoriter för varje måltid – i menyn står det ”det här eller det där”. I vissa alternativ (pita och pålägg, cornflakes och mjölk, något lätt) väljer du upp till 3 saker du gillar, var och en i sin egen portion, och i menyn står det ”det här eller det där eller det där”; kalorierna följer det du valt. Kaffe och drycker fungerar på samma sätt. Varje val balanseras, så dagen blir exakt 1 300 eller 1 500. Ändra när som helst: ⚙️ Inställningar → 🍽️ Bygg din meny, eller ”Välj upp till 3 du gillar” på måltidens kort.",
    faq_q_new_me_menu_build: "Hur byggs New Me-menyn upp?",
