    faq_a_myday_water_toggle: "Ja. Vattenglaset i 'Min Dag' (med + för ett glas till) visas som standard. För att dölja det, stäng av ”Visa vatten i 'Min Dag'” i Inställningar > Personalisering och kalender. Inget raderas – vattenspårningen fortsätter att fungera, och när reglaget slås på igen kommer glaset tillbaka.",
    faq_q_myday_water_toggle: "Kan jag dölja vattnet i 'Min Dag'?",
    myday_water_toggle_label: "Visa vatten i 'Min Dag'",
    faq_a_routine_newme_sync: "Med New Me har ⚙️ i Min Rutin en brytare 'Synka med New Me'. När den är på (standard) visas dagens New Me-måltider i Min Dag och i Min Rutin – i stället för de rutinmåltider som dolts. När den är av försvinner New Me-måltiderna från båda och rutinen blir precis som förut. Inget raderas – slår du på den igen kommer allt tillbaka och du får frågan vilka rutinmåltider som ska döljas.",
