    theme_name_watercolor_wash: "Akvarell",
    faq_a_food_list_languages: "Den inbyggda livsmedelslistan började med israeliska rätter och deras hebreiska namn. På alla andra språk visas varje livsmedel med sitt engelska namn, och sökningen hittar alla engelska namn den känner till (till exempel hittar 'broth' Clear soup); livsmedel som bara har ett hebreiskt namn visas inte där. Det som inte finns i listan kan du helt enkelt skriva med egna ord – AI-uppskattningen fungerar på alla språk.",
    faq_q_food_list_languages: "Varför visar livsmedelslistan engelska namn, och färre livsmedel, på mitt språk?",
    settings_copyright_line: "© 2026 alla rättigheter förbehållna. appen är utvecklad av eden zabari.",
    workout_ready_replace_btn: "Ersätt",
    faq_a_sport_workout_ai: "I Mina träningspass → ⋯ → Program med AI (och när tabellen är tom även på rutan bredvid de färdiga programmen). Svara med några tryck – hur många gånger i veckan, när, plats, nivå och mål, nästan alla med \"Annat\" också – och lägg gärna till en fri rad, som ett känsligt knä eller att springa 5 km till sommaren. AI:n bygger en hel vecka: typer av pass, dagar, tider, längd, intensitet, övningar och vilodagar. Innan något sparas visas en förhandsvisning: \"Lägg in i min tabell\" (i stället för tabellen eller utöver den), \"Ett annat förslag\" (upp till 3 gånger) eller \"Ändra svar\". Programmet är medvetet måttligt, och nämner du smärta eller en skada får du skonsamma alternativ och rådet att prata med en expert. Det använder samma AI-kvot som schemat och rutinen: 5 gånger gratis och 60 gånger i månaden med Premium.",
    faq_q_sport_workout_ai: "Hur skapar jag ett träningsprogram med AI?",
