    workout_ai_other: "Annat",
    workout_ai_replace: "I stället för min tabell",
    workout_ai_title: "Träningsprogram med AI",
    workout_ai_when_evening: "Kväll",
    workout_ai_when_label: "När",
    workout_ai_when_morning: "Morgon",
    workout_ai_when_noon: "Mitt på dagen",
    workout_ai_when_ph: "t.ex. efter jobbet, eller 17:30",
    workout_ai_working: "Programmet skapas…",
    faq_a_sport_workout_jar: "Varje typ av pass har sin egen färgade stjärna – löpning rosa, promenad grön, simning blå och så vidare. Varje pass du loggar den här veckan, från schemat eller separat, släpper sin stjärna i burken överst i Mina träningspass, och burken fylls mot ditt veckomål (tryck på den för att ändra målet). När du når målet lyser burken. Den lilla burken bredvid räknar hur många veckor i rad du fyllt den.",
    faq_q_sport_workout_jar: "Vad är de färgade stjärnorna och burken i Mina träningspass?",
    faq_a_sport_workout_gcal: "Ja – under ⋯ → Google Kalender (när Google Kalender är anslutet i Inställningar). Varje pass med en tid blir en händelse som upprepas varje vecka på sina dagar, och ändringar i appen uppdaterar den. Påminnelser kommer bara från appen, så Google lägger inte till egna, och passen syns aldrig dubbelt i appen. Ett nytt tryck tar bort bara träningspassen från Google Kalender.",
    faq_q_sport_workout_gcal: "Kan mina träningspass synas i Google Kalender?",
    workout_gcal_btn: "Google Kalender",
    workout_gcal_error: "Google Kalender kunde inte uppdateras – det provas igen vid nästa ändring",
    workout_gcal_not_connected: "Anslut Google Kalender i Inställningar först",
    workout_gcal_off_toast: "Träningspassen togs bort från Google Kalender",
    workout_gcal_on_toast: "Dina träningspass finns i Google Kalender",
    faq_a_sport_workout_reminder: "Ja – i ett pass, Påminnelse: 10 minuter, 30 minuter eller en timme innan, eller en egen tid (passet behöver en tid). Den ringer som dina andra påminnelser, en gång och på ett ställe: i appen om den är öppen, annars i telefonen. \"Klart\" loggar passet i historiken, och \"Inte än\" påminner igen om 5 minuter.",
    faq_q_sport_workout_reminder: "Kan jag få en påminnelse före ett pass?",
    workout_reminder_30min: "30 minuter innan",
    workout_reminder_label: "Påminnelse",
    workout_reminder_need_time: "Lägg till en tid för att få en påminnelse",
    faq_a_sport_workout_share: "Under ⋯ → Dela blir veckan en glasaktig bild i ditt temas färger, med en diskret länk till appen (på telefonen går den direkt till delningsmenyn, på datorn sparas bilden). ⋯ → PDF att skriva ut öppnar en ren sida med hela veckan och en ruta att bocka för bredvid varje pass och övning – välj \"Spara som PDF\" eller skriv ut. Programmet finns också i datarapporten i Inställningar, under Sport.",
    faq_q_sport_workout_share: "Hur delar eller skriver jag ut min träningsvecka?",
    share_image_saved: "Bilden är sparad – du kan bifoga den",
    share_save_image: "Spara bilden",
    workout_pdf_btn: "PDF att skriva ut",
    workout_share_btn: "Dela",
    faq_a_sport_workout_board: "Under ⋯ → Veckotavla är varje dag en kolumn: dra ett pass till en annan dag (på telefonen, håll först in). I ett pass lägger \"Även i Min Rutin\" in det i din rutin på dess tid och dagar, och ändringar hålls i synk åt båda hållen; från en punkt i Min Rutin gör \"Lägg till i mina träningspass\" tvärtom. En ✓ på ena stället räknas på båda, och i Min Dag syns det bara en gång – i brickan bredvid vattnet.",
    faq_q_sport_workout_board: "Hur flyttar jag ett pass till en annan dag och kopplar det till Min Rutin?",
    routine_in_workouts_btn: "Öppna i mina träningspass",
    routine_to_workout_btn: "Lägg till i mina träningspass",
    routine_to_workout_done: "Tillagt i mina träningspass 💪",
    workout_delete_confirm_routine: "Det tas bort från programmet och från Min Rutin. Pass som redan finns i historiken stannar kvar.",
    workout_moved: "Flyttat till {day}",
    workout_routine_need_time: "Lägg till en tid för att lägga det i Min Rutin",
    workout_routine_toggle: "Även i Min Rutin",
    workout_view_board: "Veckotavla",
    workout_view_timeline: "Tidslinje",
    faq_a_sport_workout_plan: "I Träningsspårning, under \"Mina träningspass\": + Pass – typ, dagar, tid, längd, intensitet och plats (även \"Annat\"). Styrke-, funktionella och simpass kan ha en lista med övningar, och Vila markerar en vilodag. Du kan också börja med ett färdigt program. Dagens pass visas stort, med hela veckan under; ✓ loggar det i träningshistoriken tillsammans med intensiteten. Under ⋯ sätter du ett veckomål (pass eller minuter) – varje pass du gör släpper sin stjärna i burken.",
    faq_a_sport_workout_today: "I Min Dag, bredvid vattnet, visar en liten bricka dagens pass – ett tryck öppnar detaljer, ✓ och ▶. ▶ startar en timer som fortsätter i brickan på startskärmen, och \"Avsluta\" loggar passet med den verkliga tiden. Om utmaningen \"Två veckor i rörelse\" i New Me pågår räknas ett loggat pass där av sig självt.",
    faq_q_sport_workout_plan: "Hur planerar jag min träningsvecka?",
