    faq_a_new_me_magic_themes: "Fem glittrande teman som ingår i New Me: Förtrollad skog, Stjärnstoft, Rosfé, Magiskt norrsken och Gyllene skymning. Välj ett i New Me (⚙️ Inställningar > Färger) eller under Inställningar > Utseende och skärm, så målar en glitterpensel skärmen i det temat. Ett magiskt tema lägger glitter i hela appen och vid varje tryck. Du kan gå tillbaka till vilket annat tema som helst när du vill.",
