    apptour_focus_text: "Allt kliver åt sidan utom den enda saken just nu – med en stor ✓. Sedan dyker nästa upp.",
    apptour_m_presets_text: "Dina sparade måltider på ett ställe: sök, nyligen använda, efter tid på dagen – och ＋ lägger till en för i dag.",
    apptour_night_text: "🌙 gör hela appen mörk, ☀️ tar tillbaka dagen.",
    apptour_noteline_text: "Skriv och tryck på ➤ – det sparas i dina anteckningar. 📝 i början byter till 🛒 inköp eller 🍎 en sparad måltid.",
    apptour_search_text: "Anteckningar, inköp, kalender, recept, anteckningsböcker, mål, tabeller och böcker – en sökning hittar allt.",
    faq_a_new_me_ai_menu: "Före menyn frågar frågeformuläret vilka måltider du äter och när (2 måltider + ett mellanmål, 2 måltider + en lätt middag, eller båda), om du äter något litet på kvällen och vilken tid, vad du inte äter och hur du dricker kaffe eller te. Sedan skapar AI 3 förslag för varje måltid – vart och ett lika stort som måltidens del av dagen, så dagen blir fortfarande exakt 1 300 eller 1 500 – plus dryckesidéer som sparas som dina fasta drycker. Välj upp till 2 favoriter per måltid; förslagen från originalmenyn finns direkt under, och under 🔄 Byt kommer de efter din personliga meny. 🔄 Andra förslag skapar en ny omgång (3 gånger per frågeformulär). För att ändra svaren eller skapa en ny meny när som helst: ⚙️ Inställningar → ✨ Personlig meny (AI).",
