    nm_sales_premium: "Hela Premium ingår",
    nm_unlock_premium: "Och hela Premium är upplåst också.",
    settings_sub_status_newme: "Premium ingår i din New Me.",
    room_back_to_shelf: "Till hyllan",
    faq_a_new_me_day_total: "Varje dag landar exakt på planen: måltiderna, cirka 150 kalorier till kaffe och drycker under dagen, och det som valts till kvällen – något litet att äta eller något att dricka. Till kvällen väljer du upp till 3 du gillar (till exempel en banan, en yoghurt eller 2 rutor mörk choklad; eller örtte, te med lite mjölk eller varm mjölk), och deras kalorier dras från måltiderna. Varje val balanserar sig självt: ett mindre eller större alternativ, en borttagen måltid, den lilla frukosten och den lilla måltiden som kommer med den, eller kvällen – skillnaden läggs till måltiderna eller dras från dem, var och en efter sin storlek, och under varje måltid står hur mycket (+ eller −) och vad som kan läggas till eller tas bort. En måltid som redan är bockad stannar som den loggades. I frågeformuläret visar varje måltid sin justering, och en liten ruta visar måltider, drycker, kvällen och totalen. Sugen på något annat den dagen? Håll totalen på samma antal kalorier eller färre.",
    faq_q_new_me_day_total: "Hur landar en New Me-dag på exakt 1 300 / 1 500, och var räknas drycker?",
