    books_quotes_chip: "Citat",
    faq_a_book_quotes: "På hyllan i det hemliga rummet (Citat), eller via den lilla etiketten 💬 Citat i Läshörnan – det är samma lista. Tryck på ”+ Citat”, skriv meningen och välj boken ur Läshörnan, eller skriv en annan titel med ”✏️ Övrigt”; författaren är valfri. ✏️ ändrar ett citat och 🗑️ tar bort det. Citaten är bokmärken som du sveper mellan – 🎨 högst upp byter till foton eller en vägg av kort.",
    faq_a_room_wish_jar: "På hyllan i det hemliga rummet står en glasburk för drömmar. Tryck på den lilla burken på översta hyllan (eller Hyllan > Önskeburken) och skriv hur du vill att ditt liv ska se ut – så vilt du vill, utan rätt eller fel. Varje önskan viks till en lapp som faller ner i burken. ”Dra en lapp” öppnar en slumpvis, och varje lapp går också att öppna för sig. Från andra gången du öppnar samma önskan kan du göra den till ett mål och dela upp den i små steg. En gång i veckan dyker en lapp med en av dina önskningar upp, stilla – ingen press, bara en påminnelse om vart du är på väg.",
    faq_q_book_quotes: "Var sparar jag citat ur böcker jag älskat?",
    faq_q_room_wish_jar: "Vad är önskeburken i det hemliga rummet?",
