    room_wish_written: "Skriven {date}",
    faq_a_saved_meals_page: "Sparade måltider har en egen sida: Kost och Mätvärden > ⭐ Sparade måltider (eller ⭐ i menyn). Sökningen högst upp hittar en måltid på namn eller ingrediens, ”Nyligen använda” visar vad du lagt till på sistone, och flikarna (Frukost, Lunch, Middag, Soppor…) visar varje tid på dagen. ”+ I dag” lägger till en måltid i dagens Dagliga Måltidsspårare, på nästa lediga plats. Tryck på en måltid för att ändra eller ta bort den, och ＋ högst upp lägger till en ny.",
