    presets_tab_sweet: "Godis",
    faq_a_notes_sticky_look: "Anteckningar är en kort lista med glaskort – 🎨 högst upp i Anteckningar byter utseende på hela Anteckningar: listan, dagknapparna högst upp och fönstret där en anteckning skrivs – glas, ren lista, registerkort eller washitejp. En anteckning som dras behåller exakt sitt eget utseende och sin egen färg. Tryck på texten i en anteckning för att öppna den – där kan du ändra den, byta färger och se när den senast skrevs. Tryck på ○ när den är klar, och × flyttar den till arkivet (🗑️ längst ner i listan tar tillbaka den). Dra den i ⠿ för att ändra ordningen, till under ”Senare” eller till en dag högst upp. ! markerar en anteckning som brådskande – den glider mjukt upp till de första raderna med en liten ”Brådskande”-etikett; ett tryck till tar bort markeringen.",
    faq_q_notes_sticky_look: "Hur öppnar, ändrar eller tar jag bort en anteckning?",
    note_to_archive_btn: "Flytta till arkivet",
    faq_a_routine_clash: "Finns det redan något på den tiden samma dagar får du två val: \"Ersätt\" – det nya får den tiden och du väljer en annan tid för det som fanns där (när du redigerar något befintligt föreslås dess tidigare tid, så att de två helt enkelt byter plats), eller \"Båda\" – båda blir kvar på samma tid, det ena under det andra. Om dagarna skiljer sig (till exempel det ena sön–tors och det andra fredag) frågas ingenting.",
    faq_q_routine_clash: "Vad händer om jag lägger något i rutinen på en tid som redan är upptagen?",
    routine_clash_both: "✌️ Båda – båda klockan {time}",
