    routine_clash_title: "Klockan {time} finns redan: {title}",
    faq_a_new_me_coffee: "Under dagens meny finns en kort sammanfattning: hur många kalorier alla dagens måltider blir tillsammans, hur mycket som är kvar för kaffe och drycker, och knappar för det kaffe och de drycker som valts – ett tryck lägger till det under Drycker. I ”Välj upp till 3 du gillar” under knapparna (och i frågeformuläret) väljer du vad som visas: vatten / kolsyrat vatten, örtte, en light-läsk, svart / americano (~5), te med lite mjölk (~25), vattenbaserat kaffe med upp till 100 ml mjölk eller växtdryck (~50), lätt varm choklad, varm mjölk eller vanligt kaffe / latte (~120).",
