    nm_late_room_line: "Något litet före läggdags · ~{n} kcal kvar i dag",
    faq_a_recipe_examples: "Under dina egna recept finns exempelrecept: frukostar, sallader, soppor, huvudrätter, tillbehör, mellanmål, efterrätter och veganska rätter, alla med tillagningstid, kalorier per portion och hur många gram en portion väger. Tryck på ett recept för att öppna det, och \"Spara i Mina Recept\" gör en egen kopia som du kan redigera. Kategorietiketterna filtrerar, och ett tryck till på samma etikett visar allt igen.",
    faq_a_recipe_grams: "I ett recept står det bredvid kalorierna \"1 portion ≈ X g\". För dina egna recept fyller du i \"Gram per portion\" (och tillagningstiden om du vill) i receptformuläret: båda är valfria, och tiden syns på receptets färgband.",
