    recipes_examples_title: "Exempelrecept",
    faq_a_recipe_scan_multi: "Ja. I \"Lägg till Recept\" trycker du på 📷 och väljer ett foto eller flera (upp till 6; en pdf går också). Vart och ett visas i en kort lista där du väljer vad det visar: Allt, Ingredienser eller Gör så här, och \"➕ Ett foto till\" lägger till fler. Tryck sedan på \"✨ Skanna receptet\": AI:n sätter ihop allt till ett recept, i rätt ordning och utan dubbla rader, och det räknas som en enda skanning. Flera foton som du väljer under 📷 Foto i AI-assistenten öppnas också här.",
    faq_q_recipe_scan_multi: "Kan jag skanna ett recept från flera foton, till exempel ingredienserna och stegen var för sig, eller två sidor?",
