    faq_a_note_written_at: "Tryck på anteckningens text för att öppna den. Inuti, under texten, syns när den senast skrevs, med exakt datum och klockslag. Bara en ändring av själva texten uppdaterar det: att arkivera och återställa, bocka av ✓, färger eller att flytta anteckningen ändrar det inte.",
