    note_written_at: "Senast skriven: {date}",
    faq_a_new_me_month: "I den magiska ryggsäcken → Månadskalender: varje dag färgas efter hur många måltider som bockades av, pilarna ‹ › byter månad, och under kalendern står månadens snitt av kalorier per dag. Ett tryck på en dag visar hur många måltider som bockades av och hur många kalorier som åts den dagen.",
