    nm_extra_line_small: "{n} kalorier till den här måltiden, från den lilla frukosten – t.ex. {ideas}",
    faq_a_new_me_small_breakfast: "En lätt frukost (cirka 170 kcal): en dinkelpita (upp till 100 kcal) med pålägg eller ost samt en grönsak – välj upp till 3 du gillar, till exempel 1 tsk chokladkräm, 1 tsk jordnötssmör eller en skiva hårdost (upp till 22 %). Eftersom den är liten kommer ”Plus en liten måltid” med den vid en annan tid (en och en halv timme senare, till exempel 11:30 → 13:00 – vilken annan tid som helst går att välja): en pita till med pålägg, proteinyoghurt och frukt, riskakor och keso, flingor och mjölk eller halv pita och ägg – upp till cirka 200 kcal, med en egen ✓. Det som fortfarande blir över delas mellan de andra måltiderna, och varje måltid visar hur mycket den fick, så dagens summa blir som i planen. Välj den i frågeformuläret, eller byt till den bara för i dag med 🔄 – till exempel när frukosten blir sen.",
