    faq_a_ai_icon: "Ja – under Inställningar > Utseende och skärm. Den mjuka bubblan är standard, och med Premium kan du också välja en svävande hjärna eller en robot.",
    faq_a_new_me_favorites: "Ja. I frågeformuläret (och när du gör om det från inställningarna) kan du välja upp till 2 alternativ för varje måltid. Det första står i menyn, med en ”eller”-rad under för det andra – ett tryck på den byter till det bara för i dag. Och om frukosten inte åts i tid flyttar ”⏰ Senare” den till senare under dagen, utan att kalorierna ändras.",
    faq_a_theme_mode: "Vissa specialteman är finast i mörkt – Akvarell, Norrsken, Barbie och de två glittertemana –, så om du väljer ett av dem byter appen till mörkt läge, och vilket annat tema som helst (även raketen) byter till ljust. Svart och Mörkgrå förblir mörka. Du kan alltid ändra efteråt med 🌙 i menyn eller med Ljust Läge i inställningarna.",
    faq_a_water_month: "I vattenspårningen. Varje post i dagens logg visar tiden då den lades till, och \"Månadstabell\" öppnar hela månaden: varje dag visar hur många liter som dracks (✓ när dagsmålet nåddes), och ett tryck på en dag visar dess poster med tider.",
