    faq_a_new_me_weight_optional: "Nej. Både nuvarande vikt och målvikt i frågeformuläret är valfria. Om en vägning läggs till senare (⚖️ Vikt under ”Min resa” i New Me eller i viktloggen) räknas framstegen från den första.",
