    nm_unlock_desc: "Menyn, utmaningarna och resan är redo – steg för steg, tillsammans.",
    nm_unlock_title: "New Me är upplåst!",
    room_reveal_star: "En ny stjärna tändes i teleskopet på taket ✨",
    faq_a_room_records: "Skivspelaren står i rummet från början, på trädstubben vid fåtöljen. Skivorna öppnar de officiella videorna till stora hits från de senaste åren på YouTube, och under dem finns fem lugna melodier som spelas här i rummet – skivan snurrar medan de spelas, och ”⏹ Stoppa” stänger av musiken.",
    faq_a_room_roof_gifts: "De kommer med den 8:e nyckeln. Ett tryck på teleskopet låter dig titta genom det: natthimlen på nära håll – dra (eller använd pilarna) för att se dig omkring – och dina avslutade utmaningar bildar en stjärnbild i det, en stjärna för varje utmaning; ett tryck på en stjärna visar vilken det var. Ett tryck på den lilla kistan öppnar den – just nu är den tom – och ett tryck till stänger den.",
    faq_q_room_records: "Vad finns på skivspelaren i det hemliga rummet?",
