    room_chest_letter: "Ett litet brev till dig",
    room_chest_letter_1: "Varje litet steg på vägen var på riktigt – och vartenda ett räknas.",
    room_chest_letter_2: "Att vara snäll mot sig själv är en del av vägen, inte en paus från den.",
