    faq_a_new_me_preview: "Ja. New Me-sidan börjar med en kort video om vad som händer inuti: frågeformuläret, lamporna i korridoren, ryggsäcken, utmaningarna och nycklarna. Under den finns allt som ingår, en titt på en dag och korta svar.",
