    nm_times_hint: "Tips: du kan ange den senaste tid du brukar äta varje måltid – till exempel 9:00 om du ofta äter runt 8.",
    room_game_marquee: "På vägen – stanna upp och njut",
    room_sand_erase_aria: "Gnid för att sudda bort det skrivna",
    faq_a_home_note_line: "Skriv på raden mitt på startskärmen och tryck på ➤ (eller Enter) – den sparas i Anteckningar. Tryck på 📝 i början av raden så blir den 🛒: då hamnar det du skriver på Inköpslistan. Tryck en gång till för 🍎: skriv några bokstäver, dina matchande sparade måltider dyker upp, och ett tryck lägger in en av dem bland dagens måltider. Med 🎤 kan du bara säga det.",
    faq_a_night_mode: "Öppna menyn ☰ och tryck på 🌙 högst upp – hela appen blir mörk. ☀️ på samma ställe tar tillbaka dagen. Det finns också i Inställningar, under Ljust Läge.",
    faq_q_home_note_line: "Hur skriver jag en snabbanteckning från startskärmen?",
    faq_q_night_mode: "Hur byter jag till nattläge?",
    menu_day_mode: "Dagläge",
    menu_night_mode: "Nattläge",
    faq_a_secret_room_yoga: "I slutet av skogsstigen finns en lysande port, och bakom den, vid ett vattenfall, sitter skogsvarelserna – Lumi, Puffi, Nixie och Sparklet – på sina mattor i en halvcirkel, och Flora, yogaläraren, sitter vänd mot dem på den enda mattan på stenen. Tryck på Flora: hon öppnar ögonen, allt kommer närmare, och samtalet börjar långsamt, med tid att läsa – Flora frågar hur alla mår, varje varelse svarar under sitt eget namn (med en liten bild av den som pratar bredvid varje rad), och sedan frågar hon dig hur det känns med människorna som står dig nära. Samtalet fortsätter efter dina svar – goda människor, någon som det är svårt med, eller att känna sig lite ensam. Varje väg slutar med ett litet uppdrag (det kan läggas direkt i Min Dag; när uppdraget är att skriva något finns det en plats att skriva på, och det sparas i den magiska dagboken) och en position med tre andetag tillsammans. ↩ går ett steg tillbaka och ✦ börjar ett nytt samtal. Nästa nyckel öppnar vattenfallet: när du sätter dig på stenen försvinner allt, och bara ljudet av vattnet blir kvar. När du lutar dig över dammen stiger en fråga upp ur vattnet – vad skulle ditt sanna jag göra i dag? – och svaret blir en liten uppgift i Min Dag. Det är en vänlig stund, inte en ersättning för att prata med en professionell.",
    faq_q_secret_room_yoga: "Vad händer på yogan i skogen?",
    room_back_to_forest: "Tillbaka till stigen",
    room_back_to_yoga: "Tillbaka till yogan",
    room_item_waterfall: "Vattenfallet",
    room_waterfall_pool_aria: "Rör vid vattnet",
    room_waterfall_rock_aria: "Sätt dig på klippan",
    room_yoga_guide_aria: "Prata med Flora",
    yg_g_alone: "Tack för att du delar. Det händer alla ibland.",
    yg_g_alone_q: "Vad skulle kännas rätt, om så bara lite?",
    yg_g_critic: "Kritik kan sticka länge. Den handlar om ett ögonblick – inte om hela människan.",
    yg_g_end: "Tack för att du kom till cirkeln. Du kan komma tillbaka när du vill.",
    yg_g_gate: "Det är okej att sätta en gräns. En gräns är ingen mur – den är en grind.",
    yg_g_good: "Så fint 💛 Vem gjorde dig gott den här veckan?",
    yg_g_good_msg: "Goda människor förtjänar att få höra det. Ett litet tack kan göra hela deras dag.",
    yg_g_hard: "Tack för att du säger det. Vad tynger mest?",
    yg_g_listen: "Att inte bli hörd är tröttsamt. Din röst spelar roll, även när den är tyst.",
