    nm_time_hour: "Timme",
    nm_time_minutes: "Minuter",
    routine_time_taken: "Det finns redan något vid den här tiden: {title}",
    faq_a_new_me_times: "I frågeformuläret i början, och när som helst i inställningarna för New Me → ”Måltidstider”. Om din rutin redan har måltidstider hämtas de därifrån – och rutinens måltider kan döljas, med New Me-måltiderna i deras ställe. Om inte väljer du hur många måltider om dagen (2 måltider + ett mellanmål / 2 måltider + en lätt middag / 2 måltider + ett mellanmål + en lätt middag) och när varje måltid är. Med ”2 måltider + ett mellanmål” blir det lunch kl. 11:30, mellanmål kl. 16:00 och middag kl. 19:00 (alla går att ändra). Det här är dina måltidstider överallt: i korridoren, i Min Dag, i Min Rutin och i påminnelserna. Vad du än väljer blir dagens kalorier desamma – det som tas bort delas mellan de andra måltiderna.",
