    nm_times_saved: "Måltidstiderna sparades",
    nm_times_title: "Måltidstider",
    faq_a_routine_exact_time: "Ja. När du beskriver en rutin för AI:n med en exakt tid (som \"16:10 trading\") sparas den precis så – utan att avrundas till hel timme. Allt som står i rutinen syns alltid på tavlan, även om timmen inte är vald i timinställningarna, och att ta bort en timme där det står något frågar först. Du kan också ändra en tid för hand: tryck på tiden i objektets fönster och välj timme och minuter.",
