    faq_a_secret_room_diary: "Bara du. Dagbokssidorna sparas i ditt konto, så de finns på alla enheter, och ingen annan kan se dem. Den magiska dagboken på skrivbordet i det hemliga rummet öppnar den, och det gör även dagboken i musikhörnan. Under den nya sidan finns en hopfälld månadstabell: en prick markerar varje dag som har en sida, och ett tryck på en dag öppnar dess sidor – där kan man också radera en sida. När dagboken väl är öppen kan den också läggas till i huvudmenyn – med reglaget i själva dagboken eller i New Mes inställningar.",
    faq_a_secret_room_places: "Varje ingång vid skogsporten öppnas med sin egen nyckel. Bakom dem: verandan vid havet (på det lilla bordet Aladdins lampa – ett tryck, och en skogsande stiger upp ur den i en magisk dimma, virvlar runt och inleder ett samtal om din önskan – se ”Vad gör lampans ande?”), gitarren och dagboken (gitarren spelar en kort, lugn melodi och tystnar av sig själv, och var och en av de tre skivorna som hänger i trädet spelar sin egen magiska melodi – tryck igen för att stoppa – och i dagboken på stubben skriver du), andningsrummet (en stilla sjö i solnedgången – en lotuslykta flyter på vattnet: tryck på den, skriv en önskan, så driver den iväg med den, långt tillbaka ut i sjön; med trollstaven kan du skriva i sanden det du vill släppa taget om, och det ligger kvar tills du suddar bort det med fingret) och skogsstigen (den öppnas på natten, och ett tryck på lyktorna växlar till dag; från den stora grenen hänger en magisk gunga, på bänken kan man sitta, och ett tryck på skylten tar den nära – en tavla med sex små frågor att bocka av). På en låst ingång syns hur många nycklar som är kvar. I slutet av stigen leder en lysande port till yogan vid vattenfallet – och därifrån till själva vattenfallet.",
    faq_q_secret_room_diary: "Vem ser dagboken?",
    faq_q_secret_room_places: "Vad finns bakom dörrarna i korridoren?",
