    dev_weather_preview_label: "Förhandsvisning – bara på ditt konto:",
    faq_a_ai_chat: "Tryck på bubblan så öppnas en chatt. Välj vad du vill göra – något till kalendern, vad du ätit, ett foto på ett recept eller en ny tabell – eller skriv bara, så förstår assistenten själv. Du kan också trycka på 🎙️ och prata i stället för att skriva. För kalendern kan du välja en gång, varje vecka eller varje dag. Svaret kommer i chatten, och därifrån kan du gå vidare till något annat eller öppna kalendern / vad du ätit.",
    faq_a_new_me_hall: "New Me börjar vid porten till en magisk skog, och varje ingång där är en plats: den runda dörren i jätteträdet leder in i det hemliga rummet, den ihåliga stocken till verandan vid havet, svamphuset till gitarren och dagboken, det lilla pilvalvet till andningsrummet, det stora pilvalvet till skogsstigen, och blombågen med stegen leder upp till stjärntaket när det har öppnats. På en låst ingång sitter ett lås. Din karaktär, Sky, svävar på stigen, och runt omkring finns spelknapparna: nästa uppdrag, veckans utmaning, den magiska ryggsäcken med hela New Me, världskartan och verktygen. Ett tryck på nycklarna högst upp förklarar hur man får nycklar.",
    faq_a_new_me_routine_meals: "När måltider är inställda i New Me och Min Rutin också har måltider frågar New Me om de ska döljas och New Me-måltiderna visas i stället – så att inget syns två gånger. Min Rutin visar då New Me-måltiderna på deras tider, med 💎 och en ✓ (ett tryck på en måltids namn öppnar ett fönster för att välja en annan måltid eller ändra dess tid, direkt där över rutinen). Inget raderas: de kommer tillbaka via ⚙️ Inställningar i New Me → Måltider i rutinen, eller genom att stänga av ”Synka med New Me” under ⚙️ i Min Rutin. Utan ett aktivt New Me kommer de tillbaka av sig själva.",
    faq_a_room_computer: "Det är en liten chatt som börjar med ”Hur går din dag hittills?” – bra, hektisk eller tung – och fortsätter med dig steg för steg, ända fram till ett litet uppdrag i slutet (som också kan gå direkt till Min Dag). Svaren kan tryckas eller skrivas fritt – det som skrivs kopplas till det närmaste svaret. ”↩ Tillbaka” går ett steg bakåt så att du kan svara annorlunda, och ”Ny chatt” börjar om när som helst. Efter en hektisk eller tung dag kan du komma tillbaka till datorn senare samma dag: ”Jag är tillbaka...” fortsätter samtalet. Den gröna lampan längst ner stänger av och sätter på datorn. Bara valen sparas, bara på den här enheten och bara till dagens slut.",
    faq_q_ai_chat: "Hur pratar jag med assistenten?",
