    dictation_mic_denied: "Mikrofonen är blockerad – tillåt den via 🔒 bredvid adressen i webbläsaren, eller i telefonens inställningar",
    faq_a_dictation: "Ja – tryck på mikrofonen 🎤 i hörnet av snabbanteckningen eller en skrivsida i anteckningsboken och prata: orden skrivs medan du pratar, på appens språk. Tryck igen för att sluta. Första gången ber webbläsaren om lov att använda mikrofonen. Fungerar i Chrome / Android och i Safari på iPhone. På en dator behövs en mikrofon och en webbläsare som Chrome, Edge eller Safari – om något saknas säger meddelandet exakt vad.",
    faq_q_dictation: "Kan jag prata i stället för att skriva?",
    faq_a_secret_room: "Ett rum som bara är ditt, inne i New Me – ett hus inuti ett jätteträd. Du ser en vägg i taget och vänder dig med pilarna (eller genom att svepa). Den första nyckeln kommer efter en ✓ på en måltid 3 olika dagar och öppnar dörren – och hela rummet med den: datorn, spelet, skivspelaren, hyllan med biblioteket i och katten. Sedan ger varje avslutad utmaning (även veckans utmaning) en nyckel som öppnar nästa plats: stjärntaket, verandan vid havet, gitarren och dagboken, andningsrummet, skogsstigen med yoga, vattenfallet och en överraskning på taket – och den 8:e kommer med en flaska från havet, med brevet från det förflutna i. När något öppnas visar en pil vägen. Den lilla luckan nederst på spelmaskinen öppnas också – än så länge är skåpet bakom den tomt. På stjärntaket faller en stjärna du trycker på som ett stjärnfall, och katten sitter på kudden.",
