    settings_good_things_label: "”3 bra saker” på kvällen",
    settings_weather_hint: "Regn, moln eller snö i hemskärmens bakgrund, efter vädret där du är. Din ungefärliga plats stannar på den här enheten och kontrolleras via vår server hos MET Norway.",
    settings_weather_label: "Väder på hemskärmens himmel",
    weather_failed: "Det gick inte att kolla vädret just nu.",
    weather_location_denied: "Ingen åtkomst till platsen – tillåt den i webbläsarens inställningar och försök igen.",
    faq_a_home_focus: "Tryck på ◎ högst upp på hemskärmen: allt försvinner utom den enda saken för nu – det som gäller den här timmen, eller nästa sak på dagens lista – med en stor ✓, plus Snabbanteckning. Efter ✓ dyker nästa sak upp. Tryck på 'Fokusläge ✕' högst upp för att få tillbaka allt.",
    faq_a_home_search: "Öppna menyn ☰ – sökningen finns högst upp. Skriv minst 2 bokstäver: resultaten kommer från dina anteckningar, inköpslistan, kalendern, recept, anteckningsböcker (titlar och sidtext), mål, tabeller och böcker, grupperade efter typ – tryck på ett för att gå direkt dit.",
    faq_a_my_day: "Min Dag samlar det som tidigare var En Titt på Idag och Min Rutin på en enda tidslinje. Längst ner på hemskärmen ser du hur mycket som är gjort, vad som gäller nu eller härnäst (med en snabb ✓) och bredvid rubriken ett glas vatten med +1. Tryck på den (eller svep uppåt) för att öppna hela dagen: överst det som saknar tid, sedan allt timme för timme – uppgifter, händelser och möten från kalendern, fasta veckotider, dagens rutin, dina måls små steg och New Me-måltider – med en linje för nu. Filtrera på Uppgifter, Rutin eller Möten & händelser. En ✓ här är samma ✓ som överallt annars (Min Rutin, Mina Mål, kalendern) och får en prästkrage i hörnet att slå ut. 'Redigera rutinen' öppnar Min Rutin (finns även i menyn), och '＋ Lägg till för idag' lägger till en uppgift för idag. Ett tryck på rubriken ”Min Dag” (eller på det lilla strecket överst) stänger den igen.",
