    faq_a_table_shopping_link: "I en ✓-kolumn som är kopplad till inköpslistan (som 'Har ingredienser' i 'Veckans måltider') har varje rad utan bock en 🛒. Ett tryck lägger till den i inköpslistan – bara en gång, aldrig dubbelt. Bocka av den här ✓ så försvinner den från listan; ta bort den från listan så visas den inte längre som 'på listan' här; markera den som köpt på listan så får raden här sin ✓ av sig själv. Alla ✓-kolumner kan kopplas eller kopplas bort i kolumnens inställningar.",
