    nm_gift_locked_view: "Presenten öppnas efter alla {n} utmaningar – {left} kvar.",
    nm_gift_intro: "Alla {n} utmaningar, steg för steg. Det här väntade:",
    nm_gift_title: "Din present",
    faq_a_new_me_letter_gift: "I början av New Me (eller senare, under Utmaningar) kan ett brev till dig själv i framtiden skrivas. När det har förseglats kan det inte läsas eller ändras förrän det öppnas: i flaskan från havet i det hemliga rummet, eller när alla 20 utmaningar är klara – där väntar även en gåva.",
    faq_q_new_me_letter_gift: "Vad är brevet från det förflutna?",
    faq_a_new_me_challenges: "🏆 Utmaningar har 20 utmaningar: 10 stora (som 5 dagar utan socker, en vecka utan kolhydrater eller gå ner 4 kg på en månad – kaloriunderskott, träning och inget socker varje dag) och 10 mini – små vanor under en vecka, som kanelkaffe utan socker. När en utmaning väljs kommer frågan om när den ska börja: i dag, i morgon, nästa vecka eller ett annat datum. En stor och en miniutmaning kan pågå samtidigt. En pågående utmaning visas överst i menyn och i Min Dag, med en ✓ för dagen. Varje vecka av en utmaning ger en fri dag (🍕) som inte bryter den, och en dag som inte bockas av räknas som fri dag – i dag och i går kan bockas av. Vissa dagar bockas av automatiskt: ett pass på 20 minuter i Träningsspårning, eller menyns måltider med ✓. Varje utmaning har ett ⓘ med vad som räknas exakt (till exempel hela listan över kolhydrater) – i själva utmaningen och bredvid den i Min Dag. Under dem finns 🌱 Personlig utveckling med 48 små utmaningar för en vecka (de räknas inte till de 20) – se ”Vad är veckans utmaning?”.",
    faq_q_new_me_challenges: "Hur fungerar utmaningarna i New Me?",
