    nm_tile_challenges: "Utmaningar",
    faq_a_workout_calories: "Ja. Varje träningspass får en uppskattning av förbrända kalorier – utifrån typ, längd och din senaste vikt (vid löpning och cykling även utifrån fart, när en sträcka är angiven). Den syns i träningslistan och i månadsöversikten (Förbränt) och läggs till dagens kaloribudget: i Daglig Måltidsspårare, i Kalori- och viktstatistik och i New Me-ringen. Det är en uppskattning, därför visas den med ~.",
    faq_q_workout_calories: "Räknas träning in i dagens kalorier?",
    faq_a_new_me_flexible_menu: "Ja. I frågeformuläret och i inställningarna väljer du hur många måltider om dagen – 2 måltider + ett mellanmål / 2 måltider + en lätt middag / 2 måltider + ett mellanmål + en lätt middag – och ➖ på ett måltidskort tar bort den (minst 3 blir kvar); ”➕ Lägg tillbaka” tar tillbaka den. Hur som helst blir dagens kalorier desamma: det som tas bort delas mellan de andra måltiderna, och under varje måltid står hur mycket som lades till och vad som passar till. ✏️ Redigera på en måltid öppnar texten – ändra vad du vill (t.ex. utan bröd eller med ett ägg till) så räknar AI om kalorier och protein. 🔄 Byt erbjuder alternativ från menyn, ⭐ Sparade och ✨ Skriv själv; varje ändring kan gälla bara i dag eller från och med nu. Och i slutet av ”Hela dagen” finns ➕ Lägg till mat – skriv vad som åts utanför menyn, så räknar AI ut det och lägger till det i dag (✕ tar bort).",
