    faq_a_goal_days_challenge: "Tryck på ＋ i Mina Mål (eller på det färdiga exemplet '🔥 8 dagar'), välj '📆 Dagarsutmaning', ange antal dagar och lägg till vad du gör varje dag (t.ex. 'En promenad på 30 minuter', 'Äta enligt min meny'). Bocka av dagens uppgifter varje dag under utmaningens stig – när alla är avbockade räknas dagen, stigen flyttas fram en sten och din 🔥-svit växer (utan dagliga uppgifter finns en enda knapp, '✓ Jag klarade det idag'). Knappen 🔁 bredvid en uppgift lägger till den i Min Rutin vid en timme du väljer: att bocka av den där bockar av den i målet också, och tvärtom. Milstolpar i ett vanligt mål kan läggas till i Min Rutin på samma sätt.",
