    vision_tagline: "Stora mål, små steg.",
    faq_a_app_tour: "Rundturen öppnas automatiskt en gång, första gången du går in. Den börjar med sina delar – tryck på en för att gå direkt dit – och visar sedan alla delar av appen (startskärmen, AI-assistenten och varje menypost) och inställningarnas fem grupper, var och en med en kort förklaring, och kikar in i några av dem (till exempel en exempelstig för ett mål, väskan och Google Calendar). Fortsätt går framåt, Tillbaka går bakåt, Hoppa över den här delen hoppar till nästa del och ✕ stänger rundturen. Du kan se den igen när du vill under Inställningar > Hjälp och användning > Apprundtur, och fortsätta där du slutade. Fortsätt och Tillbaka ligger alltid på samma ställe längst ned på skärmen, och på en dator fungerar piltangenterna också.",
    faq_q_app_tour: "Hur ser jag apprundturen igen?",
    apptour_done_text: "Har du en fråga? Hjälp och vanliga frågor i Inställningar svarar på allt, och den här rundturen finns alltid under Hjälp och användning.",
