    faq_a_other_manual_option: "Överallt där du väljer från en lista med alternativ finns också '✏️ Övrigt' - välj det och skriv exakt det du behöver. I en tabell med en valkolumn (till exempel 'Relation' i en presenttabell) trycker du på cellen, väljer '✏️ Övrigt', skriver värdet (till exempel 'Brorson') och trycker på Lägg till - det sparas som ett nytt alternativ i kolumnen, så nästa gång finns det redan i listan. Med det lilla × bredvid varje alternativ i listan tar du bort alternativet från kolumnen. När du väljer en tabellikon finns det många ikoner (bland annat färgglada klisterlappar). Det fungerar på samma sätt för kategorier för sparade måltider, receptkategorier, kategorier för återkommande utgifter (sparas som en ny egen kategori) och målkategorier i Mina Mål.",
