    nm_drinks_hint: "Skriv bara drycken – kalorierna räknas ut automatiskt och siffran kan ändras.",
    nm_slot_drinks: "Drycker",
    faq_a_new_me_tracking: "Tryck på nästa uppdrag högst upp i New Me och sedan på ✓ Jag åt för att markera nästa måltid som uppäten – hela menyn med ✓ på varje måltid finns under Hela dagen, på sidan, och dagens måltider syns också i Min Dag på hemskärmen – ett tryck på en av dem där (eller musen över den) visar exakt vad som ska ätas, med ✓ och Byt. Allt synkas med Daglig Måltidsspårare: planens måltider, drycker och allt du lägger till någon annanstans (t.ex. ett kaffe från snabbtillägg) räknas ihop i New Me och i Min Dag – inget du redan skrivit skrivs över, och att ta bort en ✓ tar bara bort New Me-delen. När alla dagens måltider är avbockade blir det ett litet firande. Under 'Drycker' loggas dagens drycker – sammanlagt upp till ~150 kcal, alltså ungefär 3 drycker på upp till ~50 kcal vardera. Skriv bara dryckens namn så fylls kalorierna i automatiskt med AI. De två raderna för kaffe/te har också fältet 'Mjölk? Hur mycket?' (t.ex. 'lite' eller '50 ml'), och beräkningen uppdateras; siffran kan ändras både före och efter att drycken lagts till. En dryck med namn och kalorier sparas automatiskt så fort du går vidare – att trycka på Lägg till är valfritt. Tryck på ☆ bredvid en dryck för att spara den som vanlig dryck – vanliga drycker visas som knappar högst upp i Drycker-kortet, och ett tryck lägger till dem för dagen. ⭐ sparar en måltid som sparad måltid. 'Dagstabell' visar vad du ätit med kalorier och protein. Den lilla 💎 bredvid fokusläget, högst upp på hemskärmen, öppnar det direkt. Kalori- och proteinvärden är AI-uppskattningar och kan innehålla fel. Åt du inte upp allt? Under en avbockad måltid drar ”Åt inte upp allt?” av en fjärdedel, hälften eller tre fjärdedelar av portionen – eller det du skriver, uträknat – och dagens kalorier uppdateras.",
    faq_q_new_me_tracking: "Hur fungerar ✓, byten och kalorier i New Me?",
    faq_a_new_me_what: "New Me är ett separat dagsmenyprogram med två färdiga planer – 1 300 eller 1 500 kalorier – byggda på 2 huvudmåltider och 2 mellanmål, med 3 alternativ för varje. Hela Premium ingår. Pris: $11.99 i månaden (avsluta när som helst) eller $99.99 en gång, livstid. Det öppnas via 💎 New Me i menyn. Innan start finns ett kort frågeformulär som börjar med en medicinsk ansvarsfriskrivning som behöver godkännas. Programmet är endast allmän information och ersätter inte en läkare eller klinisk dietist.",
    faq_q_new_me_what: "Vad är New Me och hur skaffar jag det?",
