    quick_add_ai_limit_toast: "Månadens AI-kvot är slut, så en snabbare (mindre exakt) uppskattning användes i stället. Den återställs nästa månad.",
    food_estimate_local_db_reasoning: "Hittades i vår livsmedelsdatabas, inte gissat av AI. Tryck på ”Stämmer inte” om det inte är rätt livsmedel.",
    food_clarify_milk_question: "Är {ingredient} en mjölkersättning som blandas i drycken, eller en separat portion fast föda? Ange också mängden.",
    food_ai_fallback_toast: "Den fullständiga AI-uppskattningen gick inte att nå just nu, så det här är en snabb, grov uppskattning i stället. Du kan redigera kalorierna manuellt eller försöka logga igen om en stund.",
    daily_focus_badge_title: "Påminnelse: det viktiga i dag",
    calendar_event_star_title: "Markera som viktig",
    auth_password_placeholder_login: "Lösenord",
    routine_overview_no_checks: "Inga avbockningar den här månaden än - tryck på ✓ bredvid dina rutinposter de dagar du gör dem.",
    faq_a_finance_cycle_day: "Som standard återställs din budgetsammanfattning den 1:a varje kalendermånad. Om du får lön en annan dag (säg den 10:e), ställ in den dagen här i stället - då löper din månadssammanfattning, historik och målbudget från den dagen till samma dag nästa månad, i stället för från den 1:a till månadens slut.",
    faq_q_finance_cycle_day: "Vad gör inställningen 'Återställningsdag för månadsbudget'?",
    faq_a_quick_note_view_full_lists: "I menyn ☰ finns Anteckningar och Inköpslista direkt. I fönstret Snabbanteckning (i Fokusläge) tar de små 📝 och 🛒 bredvid Lägg till dig också dit, och 🍎 lägger snabbt in en av dina sparade måltider.",
    faq_q_quick_note_view_full_lists: "Hur ser jag alla mina Anteckningar eller hela Inköpslistan från Snabbanteckning?",
    note_triage_otherdate: "Annat Datum", note_triage_otherdate_modal_title: "Välj ett datum", note_triage_otherdate_missing: "Vänligen välj ett datum", note_triage_success_otherdate: "Tillagd i ditt schema!", notes_ai_placeholder_shopping: "Lägg till i listan",
    daily_greeting_morning: "God morgon!", daily_greeting_afternoon: "God eftermiddag!", daily_greeting_evening: "God kväll!", daily_greeting_night: "God natt!", calorie_monthly_view_title: "Månadsvy", calorie_monthly_avg_label: "Dagligt genomsnitt:", calorie_monthly_avg_empty: "Ingen data loggad ännu denna månad", calorie_monthly_day_total_label: "Dagens totalt:", notes_ai_added_shopping: "Tillagd i din inköpslista", quick_note_dest_notes: "📝 Anteckningar", quick_note_dest_shopping: "🛒 Inköpslista",
    faq_q_calorie_monthly_view: "Hur ser jag min kaloriehistorik för en hel månad?", faq_a_calorie_monthly_view: "Kalorimått har ett 'Månadsvy'-kort med en kalender - varje dag du loggat mat får en prick, och månadens dagliga genomsnitt visas ovanför rutnätet. Tryck på en dag för att se exakt vad du åt och totalen. Samma sammanställning finns även med när du laddar ner din personliga rapport (PDF) från Inställningar, om avsnittet Kalorimått är ikryssat.",
    faq_q_calorie_stats_total_vs_average: "Är siffrorna för Vecka/Månad i Kalorimått en summa eller ett snitt?", faq_a_calorie_stats_total_vs_average: "Båda - det stora talet är summan (totalen) av allt som loggats under den aktuella kalenderveckan/månaden, och den lilla raden under är det dagliga snittet. Snittet delas bara med de dagar du faktiskt loggade något, inte med 7 eller hela månaden - en dag utan någon post hoppas helt enkelt över, den räknas inte som en 0 och drar inte ner snittet.",
    faq_q_weight_note: "Kan jag lägga till en anteckning i en viktregistrering?", faq_a_weight_note: "Ja - det finns ett valfritt anteckningsfält bredvid vikt-/datumfälten i Regelbunden Viktspårning (den finns längst ner i Kost och Mätvärden > Kalori- och viktstatistik, under ⚖️). Använd det för sammanhang, som \"efter ett träningspass\" eller \"morgonvägning\" - den visas bredvid den posten i historiklistan.",
    faq_q_quick_note_shopping_list: "Kan Snabbanteckning lägga till direkt i min inköpslista?", faq_a_quick_note_shopping_list: "Ja – på skrivraden mitt på startskärmen trycker du på 📝 i början: den blir 🛒, och det du skriver hamnar direkt på Inköpslistan, utan att gå via Anteckningar.",
