    faq_q_daily_focus_prompt: "Vad är den lilla påminnelsen som frågar vad som är viktigast för mig att göra idag?", faq_a_daily_focus_prompt: "Det är en daglig Premium-påminnelse: en gång om dagen visas en liten ”1”-bricka på AI-assistentens ikon. Tryck på brickan för att öppna en bubbla som frågar vad som är viktigast för dig att göra idag, med 5 färdiga förslag direkt i den (de byts ut dagligen och roterar genom ett helt år av olika teman så att de känns fräscha) plus 'Annat' för att skriva ett eget - du kan välja fler än ett. Tryck på Lägg till, så visas dina val som små påminnelseetiketter högst upp i 'Min Dag' (de är inte uppgifter att bocka av). Om du stänger den med ✕ eller trycker utanför den bleknar brickan bara för resten av dagen i stället för att försvinna. Den är på som standard, men du kan stänga av den under Inställningar > Personalisering och kalender. Inte rätt dag? Tryck på '🌙 Inte i dag' – märket försvinner till i morgon, sedan kommer frågan tillbaka som vanligt. Ett av förslagen kommer från ditt eget liv – nästa steg i månadens mål eller dagens läsning. Varje dag börjar på nytt.",
